/* Plural form for a count: 'one', 'few' or 'many'. Croatian and Russian share the rule for whole numbers
   (1, 21, 101 → one; 2–4, 22–24 → few; 0, 5–20, 25–30, 11–14 → many); fractions take the few form. English: one or many. */
window.BirdPlural=(lang,n)=>{
 const v=Math.abs(Number(n)||0);
 if(lang!=='hr'&&lang!=='ru')return v===1?'one':'many';
 if(!Number.isInteger(v))return 'few';
 const d=v%10,h=v%100;
 return d===1&&h!==11?'one':d>=2&&d<=4&&(h<12||h>14)?'few':'many';
};
/* Text of key in dict for count n: key_one / key_few / key_many when the dictionary has it, otherwise key itself. */
window.BirdPluralText=(dict,key,n,lang)=>{const t=dict?.[key+'_'+window.BirdPlural(lang,n)]||dict?.[key];return t?.[lang]??t?.en??key;};
